    return float(total / amount)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    first = 0.0
    second = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0 or radii[i] <= 0:
            continue
        coordination = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or radii[j] <= 0:
                continue
            coordination += occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        first += occ[i] * coordination
        second += occ[i] * coordination * coordination
        amount += occ[i]
    if amount <= 0 or first <= 0:
        return 0.0
    mean = first / amount
    variance = max(0.0, second / amount - mean * mean)
    return float(variance ** 0.5 / mean)

def feature(s):
    if not s:
        return 0.0
    composition = s.get('composition') or {}
    fractions = [x for x in composition.values() if x is not None and x > 0]
    amount = sum(fractions)
    if amount <= 0:
        return 0.0
    baseline = sum(x * x for x in fractions) / (amount * amount)
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    same = 0.0
    weight = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        w = occ[i] * occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        weight += w
        if sites[i].get('element') == sites[j].get('element'):
            same += w
    return float(same / weight - baseline) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    total = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0:
            continue
        nearest = None
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or occ[j] <= 0 or d <= 0:
                continue
            if nearest is None or d < nearest:
                nearest = d
        if nearest is None:
            continue
        coordination = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or occ[j] <= 0 or d <= 0 or d > 1.5 * nearest:
                continue
            coordination += occ[j] * 2.718281828459045 ** (1.0 - (d / nearest) ** 6)
        total += occ[i] * coordination
        amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    total = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0:
            continue
        first = None
        second = None
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or occ[j] <= 0 or d <= 0:
                continue
            if first is None or d < first:
                second = first
                first = d
            elif second is None or d < second:
                second = d
        if first is None or second is None:
            continue
        total += occ[i] * max(0.0, second / first - 1.0)
        amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0
